using UnityEngine;
using UnityEngine.InputSystem;
using Game.Combat;
using Game.Core;

namespace Game.Hero
{
    /// <summary>
    /// In-match Knight avatar for the Swordsman class. Spawns the Knight FBX as a
    /// child of the Hero, applies KnightMat, hooks the Animator to the standard
    /// Unity AnimatorController at Resources/Knight/KnightAnimator.controller
    /// (auto-generated by KnightAnimatorControllerSetup in Editor), then drives
    /// state changes by firing triggers — Trig_Idle / Trig_Forward / Trig_BackLeft
    /// / Trig_BackRight / Trig_Dying / Trig_Respawning / Trig_Attacking.
    ///
    /// Switched away from PlayableGraph so the user can open the AnimatorController
    /// in the Animator window and inspect / tweak the state machine visually.
    /// </summary>
    public class HeroKnightAnimator : MonoBehaviour
    {
        [Header("Visual")]
        [SerializeField] private Vector3 modelOffset = Vector3.zero;
        // 0,0,0 so the Knight faces the same direction as the Hero's transform.forward.
        // (180° offset caused the run animation to play opposite to actual movement
        // direction — classic moonwalk.)
        [SerializeField] private Vector3 modelEulerOffset = Vector3.zero;
        [SerializeField] private float modelScale = 1f;
        [SerializeField] private bool hideExistingBody = true;

        [Header("Attack")]
        [SerializeField] private float attackClipDuration = 0.6f;

        private enum AnimState { Idle, Forward, BackLeft, BackRight, Dying, Respawning, Attacking }

        private GameObject knightModel;
        private Animator animator;
        private AnimState currentState = AnimState.Idle;
        private float attackTimer;
        private bool respawning;
        private HeroInputActions inputs;
        private HealthComponent health;

        private static readonly string[] TriggerNames =
        {
            "Trig_Idle", "Trig_Forward", "Trig_BackLeft", "Trig_BackRight",
            "Trig_Dying", "Trig_Respawning", "Trig_Attacking"
        };

        private void Awake()
        {
            health = GetComponent<HealthComponent>();
            inputs = new HeroInputActions();
        }

        private void OnEnable()
        {
            inputs.Hero.Enable();
            if (health != null) health.OnDeath += OnDeath;
        }

        private void OnDisable()
        {
            inputs.Hero.Disable();
            if (health != null) health.OnDeath -= OnDeath;
            DetachRespawnEvents();
        }

        private void Start()
        {
            SpawnModel();
            if (knightModel == null) { enabled = false; return; }
            AttachAnimatorController();
            AttachRespawnEvents();
            // Force idle as the initial state.
            FireTrigger(AnimState.Idle);
            currentState = AnimState.Idle;
        }

        private void SpawnModel()
        {
            var prefab = Resources.Load<GameObject>("Knight/knight");
            if (prefab == null)
            {
                Debug.LogWarning("[HeroKnightAnimator] Resources/Knight/knight not found");
                return;
            }
            knightModel = Instantiate(prefab, transform);
            knightModel.name = "Knight_Visual";
            knightModel.transform.localPosition = modelOffset;
            knightModel.transform.localEulerAngles = modelEulerOffset;
            knightModel.transform.localScale = Vector3.one * modelScale;

            // Apply KnightMat
            var mat = Resources.Load<Material>("Knight/KnightMat");
            if (mat != null)
            {
                foreach (var r in knightModel.GetComponentsInChildren<Renderer>(true))
                {
                    var mats = new Material[r.sharedMaterials.Length];
                    for (int i = 0; i < mats.Length; i++) mats[i] = mat;
                    r.sharedMaterials = mats;
                }
            }

            animator = knightModel.GetComponentInChildren<Animator>(true);
            if (animator == null) animator = knightModel.AddComponent<Animator>();
            var avatars = Resources.LoadAll<Avatar>("Knight/knight");
            if (avatars == null || avatars.Length == 0) avatars = Resources.LoadAll<Avatar>("Knight");
            if (avatars != null && avatars.Length > 0) animator.avatar = avatars[0];
            animator.applyRootMotion = false;
            animator.updateMode = AnimatorUpdateMode.Normal;

            if (hideExistingBody)
            {
                var body = transform.Find("Body");
                if (body != null) body.gameObject.SetActive(false);
            }
        }

        private void AttachAnimatorController()
        {
            if (animator == null) return;
            var controller = Resources.Load<RuntimeAnimatorController>("Knight/KnightAnimator");
            if (controller == null)
            {
                Debug.LogWarning("[HeroKnightAnimator] Resources/Knight/KnightAnimator.controller not found — open Unity once so the Editor script auto-generates it, or run Tools/Knight/Regenerate Animator Controller.");
                return;
            }
            animator.runtimeAnimatorController = controller;
            Debug.Log("[HeroKnightAnimator] assigned controller '" + controller.name + "'");
        }

        private void Update()
        {
            if (attackTimer > 0f) attackTimer -= Time.deltaTime;
            if (inputs.Hero.Attack.WasPerformedThisFrame() && !(health != null && health.IsDead))
            {
                attackTimer = attackClipDuration;
            }
            ApplyState(ComputeState());
        }

        private AnimState ComputeState()
        {
            if (health != null && health.IsDead) return AnimState.Dying;
            if (respawning) return AnimState.Respawning;
            if (attackTimer > 0f) return AnimState.Attacking;
            Vector2 move = inputs != null ? inputs.Hero.Move.ReadValue<Vector2>() : Vector2.zero;
            if (move.y > 0.1f) return AnimState.Forward;
            if (move.y < -0.1f)
                return move.x < 0f ? AnimState.BackLeft : AnimState.BackRight;
            return AnimState.Idle;
        }

        private void ApplyState(AnimState s)
        {
            if (s == currentState) return;
            currentState = s;
            FireTrigger(s);
            Debug.Log("[HeroKnightAnimator] state -> " + s);
        }

        private void FireTrigger(AnimState s)
        {
            if (animator == null || animator.runtimeAnimatorController == null) return;
            // Reset all triggers to avoid stacking (e.g. if multiple frames flipped quickly).
            for (int i = 0; i < TriggerNames.Length; i++) animator.ResetTrigger(TriggerNames[i]);
            animator.SetTrigger(TriggerNames[(int)s]);
        }

        private void OnDeath()
        {
            currentState = AnimState.Dying;
            FireTrigger(AnimState.Dying);
        }

        private void AttachRespawnEvents()
        {
            var rm = RespawnManager.Instance;
            if (rm == null) return;
            rm.OnRespawnStarted.AddListener(OnRespawnStarted);
            rm.OnRespawnFinished.AddListener(OnRespawnFinished);
        }

        private void DetachRespawnEvents()
        {
            var rm = RespawnManager.Instance;
            if (rm == null) return;
            rm.OnRespawnStarted.RemoveListener(OnRespawnStarted);
            rm.OnRespawnFinished.RemoveListener(OnRespawnFinished);
        }

        private void OnRespawnStarted(int seconds)
        {
            respawning = true;
            currentState = AnimState.Respawning;
            FireTrigger(AnimState.Respawning);
        }

        private void OnRespawnFinished()
        {
            respawning = false;
        }
    }
}
